"""Build the browsing page from the canonical exhibit_candidates.json.
Run: python build_curation.py. No third-party package needed.
"""
import json, pathlib, zipfile
p=pathlib.Path(__file__).resolve().parent
data=json.loads((p/'exhibit_candidates.json').read_text(encoding='utf-8'))
items=data['items']
assert len(items)>=15
seen=set()
for i,x in enumerate(items, start=7):
    assert x['id'] not in seen and x['num']==f'{i:03d}', x['id']
    seen.add(x['id'])
    assert len(x['options'])==3 and type(x['answer']) is int and 0 <= x['answer'] < 3
    assert x['source_url'].startswith('https://') and x['status']
    x.setdefault('batch','第1回' if i<=21 else '第2回')
jdata=json.dumps(items,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="ja" data-theme="paper"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>奇妙な博物館｜発掘室</title><link rel="stylesheet" href="assets/design/kafka-tokens.css"><style>
:root{font:16px/1.6 var(--k-font-family-sans);color:var(--k-color-foreground);background:var(--k-color-canvas)}*{box-sizing:border-box}a{color:var(--k-color-primary)}body{margin:0}.wrap{width:min(1040px,calc(100% - 28px));margin:auto}header{background:var(--k-color-surface);border-bottom:1px solid var(--k-color-border);padding:16px 0}.back{font-size:14px}h1{font-size:clamp(28px,4vw,43px);line-height:1.25;margin:22px 0 12px}p{margin:5px 0 12px}.lead{color:var(--k-color-muted-foreground);max-width:65ch}.toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:24px 0}.toolbar input,.toolbar select{min-height:46px;padding:9px;border:1px solid var(--k-color-border);border-radius:var(--k-dimension-radius);background:white;color:inherit;font:inherit}.toolbar input{flex:1 1 240px}.toolbar select{flex:1 1 180px}button{min-height:var(--k-dimension-touch-target);cursor:pointer;padding:9px 13px;border:1px solid var(--k-color-primary);color:var(--k-color-surface);background:var(--k-color-primary);border-radius:3px;font:inherit}button.alt{border-color:var(--k-color-border);background:var(--k-color-surface);color:var(--k-color-foreground)}button[aria-pressed="true"]{background:var(--k-color-accent);color:var(--k-color-foreground);border-color:var(--k-color-primary)}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--k-color-focus);outline-offset:2px}.status{font-size:13px;color:var(--k-color-muted-foreground);min-height:26px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:12px;margin:14px 0 24px}.card{padding:19px;background:var(--k-color-surface);border:1px solid var(--k-color-border);display:flex;flex-direction:column;gap:11px;min-width:0}.category{font-size:12px;color:var(--k-color-muted-foreground)}.symbol{font-size:28px;margin-right:8px}.card h2{font-size:20px;line-height:1.35;margin:0}.teaser{flex:1;margin:0}.controls{display:flex;flex-wrap:wrap;gap:8px}.truth{border-top:1px solid var(--k-color-border);padding-top:13px;font-size:14px}.truth p{margin:0 0 10px}.quiz{border:1px solid var(--k-color-border);padding:12px;background:var(--k-color-canvas)}.quiz legend{font-weight:bold}.answers{display:grid;gap:6px;margin:8px 0}.answers button{background:var(--k-color-surface);color:var(--k-color-foreground);border-color:var(--k-color-border);text-align:left}.answers button.correct{background:color-mix(in srgb,var(--k-color-success) 13%,var(--k-color-surface));border-color:var(--k-color-success)}.answers button.incorrect{background:color-mix(in srgb,var(--k-color-danger) 12%,var(--k-color-surface));border-color:var(--k-color-danger)}.quiz-response{margin-top:8px;min-height:20px;font-weight:600}.footer{margin:25px 0 45px;border-top:1px solid var(--k-color-border);padding-top:16px;font-size:13px;color:var(--k-color-muted-foreground)}.toolbar .short{font-size:13px}.source{overflow-wrap:anywhere}#empty{padding:18px;background:var(--k-color-surface);border:1px solid var(--k-color-border)}body small{font-size:12px}@media(max-width:390px){.toolbar button{flex:1}}
</style></head><body><header><div class="wrap"><a class="back" href="index.html">← 第0号館に戻る</a></div></header><main class="wrap"><h1>新しい珍品を発掘する。</h1><p class="lead">奇妙な出来事や自然現象を40件集めました。気になる展示の説明と出典を読み、三択に答えてください。収蔵候補は自由に選べます。</p><div class="toolbar"><input id="search" type="search" placeholder="キーワードで探す（例：郵便、宇宙、カエル）" aria-label="展示候補を検索"><select id="category" aria-label="ジャンル"><option value="all">すべての分野</option></select><button id="shortlist" class="alt" aria-pressed="false" type="button">選んだ候補だけ</button><button id="export" type="button">選んだ候補を書き出す</button></div><p id="counter" class="status" aria-live="polite"></p><div id="cards" class="grid"></div><p id="empty" hidden>条件に合う展示はありません。検索を解除してください。</p><section class="footer"><p>展示候補は既存6点と区別して保管。各候補に出典URLと注記を付けました。観測結果と推定を区別して読み、資料の更新があれば展示も修正します。画像はリンク先で確認できます。</p><p id="storage-status" role="status">選択状態は、このブラウザだけに保存します。</p></section></main><script>
'use strict'; const ITEMS=__ITEMS__;
const $=id=>document.getElementById(id), key='curious-museum-curation-v1';
let selected=[]; try{let data=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(data))selected=data.filter(v=>typeof v==='string')}catch(e){$('storage-status').textContent='保存済みの候補を読み込めませんでした。'}
const categories=[...new Set(ITEMS.map(x=>x.category))]; categories.forEach(s=>{const o=document.createElement('option');o.value=s;o.textContent=s;$('category').append(o)});
const store=()=>{try{localStorage.setItem(key,JSON.stringify(selected));$('storage-status').textContent='採用候補を端末内に保存しました。'}catch(e){$('storage-status').textContent='ブラウザに保存できません。下の書き出しを使ってください。'}};
let shortlist=false, openFacts=new Set(), answers={};
function node(tag,text,cls){let e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function render(){const q=$('search').value.trim().toLowerCase(), cat=$('category').value;const results=ITEMS.filter(x=>(cat==='all'||x.category===cat)&&(!shortlist||selected.includes(x.id))&&(!q||[x.title,x.teaser,x.fact,x.category].some(s=>s.toLowerCase().includes(q))));$('cards').replaceChildren();$('empty').hidden=results.length>0;$('shortlist').setAttribute('aria-pressed',String(shortlist));$('counter').textContent=`${results.length}点表示 / ${ITEMS.length}点中 · 収蔵候補 ${selected.length}点`;
for(let x of results){let card=node('article',undefined,'card'),mark=node('div',undefined,'category');mark.append(node('span',x.icon,'symbol'),document.createTextNode(x.category+' / '+x.num+' / '+x.status));card.append(mark,node('h2',x.title),node('p',x.teaser,'teaser'));
let ctl=node('div',undefined,'controls'),open=node('button',openFacts.has(x.id)?'説明を閉じる':'説明・クイズを見る','alt'),star=node('button',selected.includes(x.id)?'候補から外す':'収蔵候補に選ぶ','alt');open.type='button';star.type='button';star.setAttribute('aria-pressed',String(selected.includes(x.id)));open.addEventListener('click',()=>{if(openFacts.has(x.id))openFacts.delete(x.id);else openFacts.add(x.id);render()});star.addEventListener('click',()=>{if(selected.includes(x.id))selected=selected.filter(v=>v!==x.id);else selected.push(x.id);store();render()});ctl.append(open,star);card.append(ctl);
if(openFacts.has(x.id)){let truth=node('section',undefined,'truth');truth.append(node('p',x.fact));let source=node('a','出典：'+x.source_name,'source');source.href=x.source_url;source.target='_blank';source.rel='noopener noreferrer';truth.append(source,node('p','注記：'+x.note,'category'));const quiz=node('div',undefined,'quiz');quiz.append(node('strong',x.question));let answerWrap=node('div',undefined,'answers');x.options.forEach((opt,i)=>{let b=node('button',opt,'alt'+(answers[x.id]===i?(i===x.answer?' correct':' incorrect'):''));b.type='button';b.addEventListener('click',()=>{answers[x.id]=i;render()});answerWrap.append(b)});quiz.append(answerWrap);if(answers[x.id]!==undefined){quiz.append(node('p',answers[x.id]===x.answer?'正解。出典も確かめてみよう。':'惜しい。正解は「'+x.options[x.answer]+'」。','quiz-response'))}truth.append(quiz);card.append(truth)}$('cards').append(card)} }
$('search').addEventListener('input',render);$('category').addEventListener('change',render);$('shortlist').addEventListener('click',()=>{shortlist=!shortlist;render()});$('export').addEventListener('click',()=>{const chosen=ITEMS.filter(x=>selected.includes(x.id));const blob=new Blob([JSON.stringify({schemaVersion:'1.0',createdAt:new Date().toISOString(),items:chosen},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download='奇妙な博物館_収蔵候補.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('storage-status').textContent=chosen.length+'件の候補をJSONに書き出しました。'});render();
</script></body></html>'''.replace('__ITEMS__',jdata)
page=page.replace('奇妙な出来事や自然現象を40件集めました。',f'奇妙な出来事や科学上の発見を{len(items)}件集めました。うち{sum(x["batch"]=="第2回" for x in items)}件が第2回調査の追加分です。')
page=page.replace('<button id="shortlist" class="alt" aria-pressed="false" type="button">選んだ候補だけ</button>',f'<button id="shortlist" class="alt" aria-pressed="false" type="button">選んだ候補だけ</button><button id="newOnly" class="alt" aria-pressed="false" type="button">新着{sum(x["batch"]=="第2回" for x in items)}件だけ</button>')
page=page.replace('let shortlist=false, openFacts=new Set()', 'let shortlist=false, onlyNew=false, openFacts=new Set()')
page=page.replace("(cat==='all'||x.category===cat)&&(!shortlist", "(!onlyNew||x.batch==='第2回')&&(cat==='all'||x.category===cat)&&(!shortlist")
page=page.replace("$('shortlist').setAttribute('aria-pressed',String(shortlist));", "$('shortlist').setAttribute('aria-pressed',String(shortlist));$('newOnly').setAttribute('aria-pressed',String(onlyNew));")
page=page.replace("$('shortlist').addEventListener('click',()=>{shortlist=!shortlist;render()});", "$('shortlist').addEventListener('click',()=>{shortlist=!shortlist;render()});$('newOnly').addEventListener('click',()=>{onlyNew=!onlyNew;render()});")
page=page.replace('@media(max-width:390px){.toolbar button{flex:1}}','@media(max-width:540px){.toolbar input,.toolbar select{flex:1 1 100%}.toolbar button{flex:1 1 calc(50% - 10px);white-space:normal}#export{flex-basis:100%}}')
assert 'newOnly' in page
(p/'curation.html').write_text(page,encoding='utf-8')
(p/'CANDIDATES.md').write_text(f'# 奇妙な博物館｜展示候補{len(items)}件（2026-10-31）\n\n元の正式展示6件とは別。クイズ・一次資料・注意点の正本は `exhibit_candidates.json`。\n\n| 番号 | 候補 | 分野 | 出典 | 状態 |\n|---|---|---|---|---|\n'+'\n'.join('| '+x['num']+' | '+x['title']+' | '+x['category']+' | [確認]('+x['source_url']+') | '+x['status']+' |' for x in items)+'\n',encoding='utf-8')
print('built',len(items),'items, page bytes',len(page.encode('utf-8')))
